/* prog60_inventory_sim.c
 *
 * Re‑implementation of the original obfuscated program.
 * The program processes command‑line arguments in groups of three:
 *
 *   OP  SKU  QTY
 *
 * OP is a one‑character string:
 *   'R' – restock   (adds QTY to the stock of SKU)
 *   'S' – sell      (removes QTY from the stock of SKU and adds revenue)
 *
 * The program prints messages exactly as the original binary does:
 *
 *   RESTOCK sku=%ld qty=%ld
 *   SELL sku=%ld qty=%ld revenue+=%ld
 *   INSUFFICIENT_STOCK sku=%ld
 *   INVALID_SKU
 *   INVALID_OP
 *
 * After all arguments are processed it prints the final stock vector
 * (five SKUs, always printed, values separated by commas) and the total
 * revenue accumulated during the sell operations.
 *
 * The behaviour (including the order of messages, commas, new‑lines,
 * and spaces) matches the original program byte‑for‑byte.
 */

#include <stdio.h>
#include <stdlib.h>

#define NUM_SKU 5

/* Global arrays as in the original binary.  Both are placed in the BSS,
 * therefore they are zero‑initialised.  The `price` array is never
 * initialised in the binary, so its values are all zero, which makes the
 * revenue printed by the original program always zero. */
static long stock[NUM_SKU] = {0};
static const long price[NUM_SKU] = {0, 0, 0, 0, 0};

int main(int argc, char **argv)
{
    long revenue = 0;
    int i = 1;                     /* start after program name */

    while (i + 2 < argc) {         /* need three arguments per command */
        const char *op = argv[i];
        long sku = strtol(argv[i + 1], NULL, 10);
        long qty = strtol(argv[i + 2], NULL, 10);

        /* operation must be a single character */
        if (op[0] == '\0' || op[1] != '\0') {
            puts("INVALID_OP");
            i += 3;
            continue;
        }

        if (op[0] == 'R') {        /* RESTOCK */
            if (sku < 0 || sku >= NUM_SKU) {
                puts("INVALID_SKU");
            } else {
                stock[sku] += qty;
                printf("RESTOCK sku=%ld qty=%ld\n", sku, qty);
            }
        } else if (op[0] == 'S') { /* SELL */
            if (sku < 0 || sku >= NUM_SKU) {
                puts("INVALID_SKU");
            } else if (qty < 0) {
                printf("INSUFFICIENT_STOCK sku=%ld\n", sku);
            } else if (stock[sku] < qty) {
                printf("INSUFFICIENT_STOCK sku=%ld\n", sku);
            } else {
                stock[sku] -= qty;
                revenue += price[sku] * qty;
                printf("SELL sku=%ld qty=%ld revenue+=%ld\n",
                       sku, qty, price[sku] * qty);
            }
        } else {
            puts("INVALID_OP");
        }

        i += 3;
    }

    /* final report */
    printf("FINAL stock=");
    for (int s = 0; s < NUM_SKU; ++s) {
        printf("%ld", stock[s]);
        putchar(',');               /* trailing comma is part of original output */
    }
    printf(" revenue=%ld\n", revenue);
    return 0;
}
